class Playlist
  include Enumerable

  def initialize(*tracks)
    @tracks = tracks
  end

  def each
    return enum_for(__method__) unless block_given?

    @tracks.each { |track| yield track }
  end
end

playlist = Playlist.new('intro', 'interview', 'review')
p playlist.select { |track| track.length > 6 }
p playlist.map(&:upcase)
p playlist.find { |track| track.start_with?('r') }

